                    println!("lightningcss 1.0.0-alpha.70");
                    std::process::exit(0);
                }
                _ => {
                    if !arg.starts_with('-') {
                        result.input_files.push(PathBuf::from(arg));
                    }
                }
            }
            i += 1;
        }

        result
    }
}

fn print_help() {
