fn main() {
    let args = Args::parse();

    // Check for conflicting options
    if args.input_files.len() > 1 && args.output_file.is_some() {
        eprintln!("Cannot output to file with multiple inputs. Use --output-dir instead.");
        std::process::exit(1);
    }

    if args.input_files.is_empty() && args.output_dir.is_some() {
        eprintln!("Cannot use --output-dir with stdin input.");
        std::process::exit(1);
    }

    if args.input_files.len() > 1 && args.output_file.is_none() && args.output_dir.is_none() {
        eprintln!("Cannot output to stdout with multiple inputs. Use --output-dir instead.");
        std::process::exit(1);
    }

    // Handle input
    if args.input_files.is_empty() {
        // Read from stdin
        let mut input = String::new();
        io::stdin().read_to_string(&mut input).expect("Failed to read from stdin");
        process_css(&input, None, &args);
    } else if args.input_files.len() == 1 {
        // Read from single file
        let file_path = &args.input_files[0];
        let input = fs::read_to_string(file_path).expect("Failed to read input file");
        process_css(&input, Some(file_path), &args);
    } else {
        // Multiple files with output directory
        let output_dir = args.output_dir.as_ref().expect("output-dir required");
        fs::create_dir_all(output_dir).expect("Failed to create output directory");

        for file_path in &args.input_files {
            let input = fs::read_to_string(file_path).expect("Failed to read input file");
            let file_name = file_path.file_name().expect("Invalid filename");
            let output_path = output_dir.join(file_name);

            process_css_to_file(&input, Some(file_path), &args, &output_path);
        }
    }
}

fn process_css(input: &str, file_path: Option<&Path>, args: &Args) {
    let file_name = file_path.and_then(|p| p.to_str()).unwrap_or("stdin");

    match parse_css(input, file_name, args.error_recovery) {
        Ok(stylesheet) => {
            let output = if args.css_modules {
                format_css_modules(&stylesheet, &args)
            } else {
                format_css(&stylesheet, &args)
            };

            if let Some(output_file) = &args.output_file {
                fs::write(output_file, &output).expect("Failed to write output file");
                if args.sourcemap {
                    let map = sourcemap::generate_sourcemap(file_path, output_file);
                    let map_path = format!("{}.map", output_file.display());
                    fs::write(&map_path, &map).expect("Failed to write sourcemap");
                }
            } else {
                print!("{}", output);
            }
        }
        Err(e) => {
            if !args.error_recovery {
                eprintln!("{}", e);
                std::process::exit(1);
            }
        }
    }
}

fn process_css_to_file(input: &str, file_path: Option<&Path>, args: &Args, output_path: &Path) {
    let file_name = file_path.and_then(|p| p.to_str()).unwrap_or("stdin");

    match parse_css(input, file_name, args.error_recovery) {
        Ok(stylesheet) => {
            let output = if args.css_modules {
                format_css_modules(&stylesheet, &args)
            } else {
                format_css(&stylesheet, &args)
            };

            fs::write(output_path, &output).expect("Failed to write output file");

            if args.sourcemap {
                let map = sourcemap::generate_sourcemap(file_path, Some(output_path));
                let map_path = format!("{}.map", output_path.display());
                fs::write(&map_path, &map).expect("Failed to write sourcemap");
            }
        }
        Err(e) => {
            if !args.error_recovery {
                eprintln!("{}", e);
                std::process::exit(1);
            }
        }
    }
}

fn format_css(stylesheet: &parser::Stylesheet, args: &Args) -> String {
    if args.minify {
        CssMinifier::new().minify(stylesheet)
    } else {
        CssFormatter::new().format(stylesheet)
    }
}

fn format_css_modules(stylesheet: &parser::Stylesheet, args: &Args) -> String {
    let pattern = args.css_modules_pattern.clone().unwrap_or_else(|| "[hash]-[local]".to_string());
    let processor = CssModulesProcessor::new(pattern, args.css_modules_dashed_idents);
    let (code, exports) = processor.process(stylesheet);

    let output = if args.minify {
        CssMinifier::new().minify_str(&code)
    } else {
        code
    };

    json_encode(&output, &exports)
}

fn json_encode(code: &str, exports: &std::collections::HashMap<String, (String, bool)>) -> String {
    let mut result = String::from("{\"code\":");
    result.push('"');
    for ch in code.chars() {
        match ch {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            _ => result.push(ch),
        }
    }
    result.push('"');
    result.push(',');
    result.push_str("\"exports\":{");

    let mut first = true;
    for (key, (scoped_name, is_referenced)) in exports.iter() {
        if !first {
            result.push(',');
        }
        first = false;
        result.push('"');
        result.push_str(key);
        result.push_str("\":{\"name\":\"");
        result.push_str(scoped_name);
        result.push_str("\",\"composes\":[],\"isReferenced\":");
        result.push_str(if *is_referenced { "true" } else { "false" });
        result.push('}');
    }

    result.push_str("}}");
    result
}
