        };

        let mut i = 1;
        while i < args.len() {
            let arg = &args[i];
            match arg.as_str() {
                "-m" | "--minify" => result.minify = true,
                "-o" | "--output-file" => {
                    i += 1;
                    if i < args.len() {
                        result.output_file = Some(PathBuf::from(&args[i]));
                    }
                }
                "-d" | "--output-dir" => {
                    i += 1;
                    if i < args.len() {
                        result.output_dir = Some(PathBuf::from(&args[i]));
                    }
                }
                "--css-modules" => result.css_modules = true,
                "--css-modules-pattern" => {
                    i += 1;
                    if i < args.len() {
                        result.css_modules_pattern = Some(args[i].clone());
                    }
                }
                "--css-modules-dashed-idents" => result.css_modules_dashed_idents = true,
                "--custom-media" => result.custom_media = true,
                "--sourcemap" => result.sourcemap = true,
                "-t" | "--targets" => {
                    i += 1;
                    if i < args.len() {
                        result.targets = Some(args[i].clone());
                    }
                }
                "--bundle" => result.bundle = true,
                "--error-recovery" => result.error_recovery = true,
                "--browserslist" => result.browserslist = true,
                "-h" | "--help" => {
                    print_help();
                    std::process::exit(0);
                }
                "-V" | "--version" => {
                    println!("lightningcss 1.0.0-alpha.70");
                    std::process::exit(0);
                }
                _ => {
                    if !arg.starts_with('-') {
                        result.input_files.push(PathBuf::from(arg));
                    }
                }
            }
            i += 1;
        }

        result
    }
}

fn print_help() {
    println!("lightningcss 1.0.0-alpha.70");
    println!("Devon Govett <devongovett@gmail.com>");
    println!("A CSS parser, transformer, and minifier");
    println!();
    println!("USAGE:");
    println!("    executable [OPTIONS] [INPUT_FILE]...");
    println!();
    println!("ARGS:");
    println!("    <INPUT_FILE>...    Target CSS file (default: stdin)");
    println!();
    println!("OPTIONS:");
    println!("        --browserslist");
    println!();
    println!("        --bundle");
    println!();
    println!("        --css-modules [<CSS_MODULES>]");
    println!("            Enable CSS modules in output. If no filename is provided, <output_file>.json will be");
    println!("            used. If no --output-file is specified, code and exports will be printed to stdout as");
    println!("            JSON");
    println!();
    println!("        --css-modules-dashed-idents");
    println!();
    println!("        --css-modules-pattern <CSS_MODULES_PATTERN>");
    println!();
    println!("        --custom-media");
    println!("            Enable parsing custom media queries");
    println!();
    println!("    -d, --output-dir <OUTPUT_DIR>");
    println!("            Destination directory to output into");
    println!();
    println!("        --error-recovery");
    println!();
    println!("    -h, --help");
    println!("            Print help information");
    println!();
    println!("    -m, --minify");
    println!("            Minify the output");
    println!();
