                let class_name = chars[start..i].iter().collect::<String>();
                let scoped_name = self.scoped_name(&class_name);
                locals.insert(class_name, scoped_name.clone());
                result.push_str(&scoped_name);
            } else if chars[i] == '#' {
                result.push_str(&current);
                current.clear();
                result.push('#');
