use crate::parser::{Stylesheet, CssRule, Declaration};

pub struct CssFormatter;

impl CssFormatter {
    pub fn new() -> Self {
        CssFormatter
    }

    pub fn format(&self, stylesheet: &Stylesheet) -> String {
        let mut output = String::new();

        for (i, rule) in stylesheet.rules.iter().enumerate() {
            if i > 0 {
                output.push('\n');
            }
            output.push_str(&self.format_rule(rule, 0));
        }

        if !output.is_empty() {
            output.push('\n');
        }
        output
    }

    fn format_rule(&self, rule: &CssRule, indent: usize) -> String {
        match rule {
            CssRule::StyleRule { selector, declarations } => {
                self.format_style_rule(selector, declarations, indent)
            }
            CssRule::AtRule { name, params, rules } => {
                self.format_at_rule(name, params, rules.as_ref(), indent)
            }
            CssRule::Comment(_) => String::new(),
        }
    }

    fn format_style_rule(&self, selector: &str, declarations: &[Declaration], indent: usize) -> String {
        let mut output = String::new();
        let indent_str = "  ".repeat(indent);

        output.push_str(&indent_str);
        output.push_str(selector);
        output.push_str(" {\n");

        for decl in declarations {
            output.push_str(&format!(
                "{}  {}: {};\n",
                indent_str,
                decl.property,
                self.normalize_value(&decl.value)
            ));
        }

        output.push_str(&indent_str);
        output.push_str("}");

        output
    }

    fn format_at_rule(&self, name: &str, params: &str, rules: Option<&Vec<CssRule>>, indent: usize) -> String {
        let mut output = String::new();
        let indent_str = "  ".repeat(indent);

        output.push_str(&indent_str);
        output.push_str("@");
        output.push_str(name);

        if !params.is_empty() {
            output.push(' ');
            output.push_str(params);
        }

        if let Some(nested_rules) = rules {
            output.push_str(" {\n");

            for rule in nested_rules {
                output.push_str(&self.format_rule(rule, indent + 1));
                output.push('\n');
            }

            output.push_str(&indent_str);
            output.push_str("}");
        } else {
            output.push(';');
        }

        output
    }

    fn normalize_value(&self, value: &str) -> String {
        let value = value.trim();

        // Normalize hex colors
        let value = if value == "#ff0000" || value == "#FF0000" {
            "red".to_string()
        } else if value == "#ffffff" || value == "#FFFFFF" || value == "#fff" {
            "#fff".to_string()
        } else if value == "#0000ff" || value == "#0000FF" {
            "#00f".to_string()
        } else if value == "#000000" || value == "#000000" {
            "#000".to_string()
        } else if value == "#ffff00" || value == "#FFFF00" {
            "#ff0".to_string()
        } else {
            value.to_string()
        };

        // Normalize units
        let value = value.replace("0px", "0");

        value
    }
}
