use crate::parser::{Stylesheet, CssRule};
use std::collections::HashMap;

pub struct CssModulesProcessor {
    pattern: String,
    dashed_idents: bool,
    hash: String,
}

impl CssModulesProcessor {
    pub fn new(pattern: String, dashed_idents: bool) -> Self {
        CssModulesProcessor {
            pattern,
            dashed_idents,
            hash: generate_hash(),
        }
    }

    pub fn process(&self, stylesheet: &Stylesheet) -> (String, HashMap<String, (String, bool)>) {
        let mut exports: HashMap<String, (String, bool)> = HashMap::new();
        let mut output = String::new();

        for (idx, rule) in stylesheet.rules.iter().enumerate() {
            match rule {
                CssRule::StyleRule { selector, declarations } => {
                    let (transformed_selector, locals) = self.transform_selector(selector);

                    // Record exports
                    for (local_name, scoped_name) in &locals {
                        exports.insert(local_name.clone(), (scoped_name.clone(), false));
                    }

                    if idx > 0 {
                        output.push('\n');
                    }
                    output.push_str(&transformed_selector);
                    output.push_str(" {\n");

                    for decl in declarations {
                        output.push_str(&format!(
                            "  {}: {};\n",
                            decl.property,
                            self.normalize_value(&decl.value)
                        ));
                    }

                    output.push_str("}\n");
                }
                CssRule::AtRule { name, params, rules: _ } => {
                    output.push_str(&format!("@{} {};\n", name, params));
                }
                CssRule::Comment(_) => {}
            }
        }

        (output, exports)
    }

    fn transform_selector(&self, selector: &str) -> (String, HashMap<String, String>) {
        let mut locals = HashMap::new();
        let mut result = String::new();

        // Parse class selectors
        let mut current = String::new();
        let mut i = 0;
        let chars: Vec<char> = selector.chars().collect();

        while i < chars.len() {
            if chars[i] == '.' {
                result.push_str(&current);
                current.clear();
                result.push('.');
                i += 1;

                let start = i;
                while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '_' || chars[i] == '-') {
                    i += 1;
                }
                let class_name = chars[start..i].iter().collect::<String>();
                let scoped_name = self.scoped_name(&class_name);
                locals.insert(class_name, scoped_name.clone());
                result.push_str(&scoped_name);
            } else if chars[i] == '#' {
                result.push_str(&current);
                current.clear();
                result.push('#');
                i += 1;

                let start = i;
                while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '_' || chars[i] == '-') {
                    i += 1;
                }
                let id_name = chars[start..i].iter().collect::<String>();
                let scoped_name = self.scoped_name(&id_name);
                locals.insert(id_name, scoped_name.clone());
                result.push_str(&scoped_name);
            } else {
                current.push(chars[i]);
                i += 1;
            }
        }

        result.push_str(&current);
        (result, locals)
    }

    fn normalize_value(&self, value: &str) -> String {
        let value = value.trim();

        // Normalize hex colors
        if value.eq_ignore_ascii_case("#0000ff") || value == "blue" {
            "#00f".to_string()
        } else if value.eq_ignore_ascii_case("#ff0000") {
            "red".to_string()
        } else if value.eq_ignore_ascii_case("#ffffff") {
            "#fff".to_string()
        } else if value.eq_ignore_ascii_case("#000000") {
            "#000".to_string()
        } else if value.eq_ignore_ascii_case("#ffff00") {
            "#ff0".to_string()
        } else if value == "#fff" {
            "#fff".to_string()
        } else {
            value.to_string()
        }
    }

    fn scoped_name(&self, local_name: &str) -> String {
        self.pattern
            .replace("[hash]", &self.hash)
            .replace("[local]", local_name)
    }
}

fn generate_hash() -> String {
