                    i += 1;
                    if i < args.len() {
                        result.output_file = Some(PathBuf::from(&args[i]));
                    }
                }
                "-d" | "--output-dir" => {
                    i += 1;
                    if i < args.len() {
                        result.output_dir = Some(PathBuf::from(&args[i]));
                    }
                }
                "--css-modules" => result.css_modules = true,
                "--css-modules-pattern" => {
                    i += 1;
                    if i < args.len() {
                        result.css_modules_pattern = Some(args[i].clone());
