#[derive(Debug, Clone)]
pub struct Stylesheet {
    pub rules: Vec<CssRule>,
    pub errors: Vec<String>,
}

#[derive(Debug, Clone)]
pub enum CssRule {
    StyleRule {
        selector: String,
        declarations: Vec<Declaration>,
    },
    AtRule {
        name: String,
        params: String,
        rules: Option<Vec<CssRule>>,
    },
    Comment(String),
}

#[derive(Debug, Clone)]
pub struct Declaration {
    pub property: String,
    pub value: String,
    pub important: bool,
}

pub struct CssParser {
    input: String,
    pos: usize,
    line: usize,
    col: usize,
    error_recovery: bool,
    errors: Vec<String>,
}

impl CssParser {
    pub fn new(input: &str, error_recovery: bool) -> Self {
        CssParser {
            input: input.to_string(),
            pos: 0,
            line: 0,
            col: 0,
            error_recovery,
            errors: Vec::new(),
        }
    }

    fn current_char(&self) -> Option<char> {
        self.input.chars().nth(self.pos)
    }

    fn peek_char(&self, offset: usize) -> Option<char> {
        self.input.chars().nth(self.pos + offset)
    }

    fn advance(&mut self) {
        if let Some(ch) = self.current_char() {
            if ch == '\n' {
                self.line += 1;
                self.col = 0;
            } else {
                self.col += 1;
            }
            self.pos += 1;
        }
    }

    fn skip_whitespace(&mut self) {
        while let Some(ch) = self.current_char() {
            if ch.is_whitespace() {
                self.advance();
            } else {
                break;
            }
        }
    }

    fn parse_comment(&mut self) -> Option<String> {
        if self.current_char() == Some('/') && self.peek_char(1) == Some('*') {
            let start = self.pos;
            self.advance(); // skip /
            self.advance(); // skip *

            while let Some(ch) = self.current_char() {
                if ch == '*' && self.peek_char(1) == Some('/') {
                    self.advance();
                    self.advance();
                    return Some(self.input[start..self.pos].to_string());
                }
                self.advance();
            }
        }
        None
    }

    fn parse_selector(&mut self) -> String {
        let start = self.pos;
        let mut _depth = 0;

        while let Some(ch) = self.current_char() {
            if ch == '{' {
                break;
            }
            if ch == '(' {
                _depth += 1;
            } else if ch == ')' {
                _depth -= 1;
            }
            self.advance();
        }

        self.input[start..self.pos].trim().to_string()
    }

    fn parse_declaration_value(&mut self) -> String {
        let start = self.pos;
        let mut depth = 0;

        while let Some(ch) = self.current_char() {
            if ch == '(' {
                depth += 1;
            } else if ch == ')' {
                depth -= 1;
            } else if ch == ';' && depth == 0 {
                break;
            } else if ch == '}' && depth == 0 {
                break;
            }
            self.advance();
        }

        self.input[start..self.pos].trim().to_string()
    }

    fn parse_declarations(&mut self) -> Vec<Declaration> {
        let mut declarations = Vec::new();

        self.skip_whitespace();
        if self.current_char() != Some('{') {
            return declarations;
        }
        self.advance(); // skip {

        while self.current_char() != Some('}') && self.current_char().is_some() {
            self.skip_whitespace();

            if let Some(_comment) = self.parse_comment() {
                continue;
            }

            if self.current_char() == Some('}') {
                break;
            }

            let prop_start = self.pos;
            while let Some(ch) = self.current_char() {
                if ch == ':' {
                    break;
                }
                self.advance();
            }

            let property = self.input[prop_start..self.pos].trim().to_lowercase();

            if self.current_char() != Some(':') {
                continue;
            }
            self.advance(); // skip :

            self.skip_whitespace();
            let value = self.parse_declaration_value();

            let important = value.trim_end().ends_with("!important");
            let clean_value = if important {
                value.trim_end_matches("!important").trim().to_string()
            } else {
                value
            };

            if self.current_char() == Some(';') {
                self.advance();
            }

            if !property.is_empty() && !clean_value.is_empty() {
                declarations.push(Declaration {
                    property,
                    value: clean_value,
                    important,
                });
            }
        }

        if self.current_char() == Some('}') {
            self.advance();
        }

        declarations
    }

    pub fn parse(&mut self) -> Result<Stylesheet, String> {
        let mut rules = Vec::new();

        while self.current_char().is_some() {
            self.skip_whitespace();

            if let Some(_comment) = self.parse_comment() {
                continue;
            }

            if self.current_char().is_none() {
                break;
            }

            if self.current_char() == Some('@') {
                self.advance();
                match self.parse_at_rule() {
                    Ok(at_rule) => rules.push(at_rule),
                    Err(e) => {
                        if self.error_recovery {
                            self.errors.push(e);
                            // Skip to next rule
                            while self.current_char().is_some() && self.current_char() != Some('}') {
                                self.advance();
                            }
                            if self.current_char() == Some('}') {
                                self.advance();
                            }
                        } else {
                            return Err(e);
                        }
                    }
                }
            } else {
                let selector = self.parse_selector();
                if !selector.is_empty() {
                    let declarations = self.parse_declarations();
                    rules.push(CssRule::StyleRule {
                        selector,
                        declarations,
                    });
                } else if self.current_char().is_some() {
                    // Record an error for invalid syntax
                    let error_char = self.current_char().unwrap_or('?');
                    let error_str = if error_char.is_alphabetic() {
                        format!("Unexpected token Ident(\"{}\") at stdin-{}:{}:{}", error_char, self.line, self.line, self.col)
                    } else {
                        format!("Unexpected token at stdin-{}:{}:{}", self.line, self.line, self.col)
                    };

                    if self.error_recovery {
                        self.errors.push(error_str);
                        self.advance();
                    } else {
                        return Err(error_str);
                    }
                }
            }
        }

        if self.error_recovery {
            Ok(Stylesheet { rules, errors: self.errors.clone() })
        } else {
            Ok(Stylesheet { rules, errors: Vec::new() })
        }
    }

    fn parse_at_rule(&mut self) -> Result<CssRule, String> {
        let name_start = self.pos;
        while let Some(ch) = self.current_char() {
            if ch == '{' || ch == ';' || ch.is_whitespace() {
                break;
            }
            self.advance();
        }
        let name = self.input[name_start..self.pos].to_string();

        self.skip_whitespace();

        let params_start = self.pos;
        while let Some(ch) = self.current_char() {
            if ch == '{' || ch == ';' {
                break;
            }
            self.advance();
        }
        let params = self.input[params_start..self.pos].trim().to_string();

        self.skip_whitespace();

        let rules = if self.current_char() == Some('{') {
            self.advance(); // skip {
            let mut nested_rules = Vec::new();

            while self.current_char() != Some('}') && self.current_char().is_some() {
                self.skip_whitespace();

                if let Some(_comment) = self.parse_comment() {
                    continue;
                }

                if self.current_char() == Some('}') {
                    break;
                }

                let selector = self.parse_selector();
                if !selector.is_empty() {
                    let declarations = self.parse_declarations();
                    nested_rules.push(CssRule::StyleRule {
                        selector,
                        declarations,
                    });
                }
            }

            if self.current_char() == Some('}') {
                self.advance();
            }

            Some(nested_rules)
        } else if self.current_char() == Some(';') {
            self.advance();
            None
        } else {
            None
        };

        Ok(CssRule::AtRule {
            name,
            params,
            rules,
        })
    }
}

pub fn parse_css(input: &str, _file_name: &str, error_recovery: bool) -> Result<Stylesheet, String> {
    let mut parser = CssParser::new(input, error_recovery);
    parser.parse()
}
