    custom_media: bool,
    sourcemap: bool,
    targets: Option<String>,
    bundle: bool,
    error_recovery: bool,
    browserslist: bool,
}

impl Args {
    fn parse() -> Self {
        let args: Vec<String> = env::args().collect();
        let mut result = Args {
            input_files: Vec::new(),
            minify: false,
            output_file: None,
            output_dir: None,
            css_modules: false,
            css_modules_pattern: None,
