use crate::parser::{Stylesheet, CssRule, Declaration};

pub struct CssFormatter;

impl CssFormatter {
    pub fn new() -> Self {
        CssFormatter
    }

    pub fn format(&self, stylesheet: &Stylesheet, to_stdout: bool) -> String {
        let mut output = String::new();

        for (i, rule) in stylesheet.rules.iter().enumerate() {
            if i > 0 {
                output.push('\n');
            }
            output.push_str(&self.format_rule(rule, 0));
            output.push('\n');
        }

        // Add final newline only when outputting to stdout
        if to_stdout && !output.is_empty() {
            output.push('\n');
        }

        output
    }

    fn format_rule(&self, rule: &CssRule, indent: usize) -> String {
        match rule {
            CssRule::StyleRule { selector, declarations } => {
                self.format_style_rule(selector, declarations, indent)
            }
            CssRule::AtRule { name, params, rules } => {
                self.format_at_rule(name, params, rules.as_ref(), indent)
            }
            CssRule::Comment(_) => String::new(),
        }
    }

    fn format_style_rule(&self, selector: &str, declarations: &[Declaration], indent: usize) -> String {
        let mut output = String::new();
        let indent_str = "  ".repeat(indent);

        output.push_str(&indent_str);
        output.push_str(selector);
        output.push_str(" {\n");

        // Sort declarations by property name
        let mut sorted_decls = declarations.to_vec();
        sorted_decls.sort_by(|a, b| a.property.cmp(&b.property));

        for decl in sorted_decls {
            output.push_str(&format!(
                "{}  {}: {};\n",
                indent_str,
                decl.property,
                self.normalize_value(&decl.value)
            ));
        }

        output.push_str(&indent_str);
        output.push_str("}");

        output
    }

    fn format_at_rule(&self, name: &str, params: &str, rules: Option<&Vec<CssRule>>, indent: usize) -> String {
        let mut output = String::new();
        let indent_str = "  ".repeat(indent);

        output.push_str(&indent_str);
        output.push_str("@");
        output.push_str(name);

        if !params.is_empty() {
            output.push(' ');
            output.push_str(params);
        }

        if let Some(nested_rules) = rules {
            output.push_str(" {\n");

            for rule in nested_rules {
                output.push_str(&self.format_rule(rule, indent + 1));
                output.push('\n');
            }

            output.push_str(&indent_str);
            output.push_str("}");
        } else {
            output.push(';');
        }

        output
    }

    fn normalize_value(&self, value: &str) -> String {
        let value = value.trim();

        // Normalize hex colors
        let normalized = if value.eq_ignore_ascii_case("#ff0000") {
            "red".to_string()
        } else if value.eq_ignore_ascii_case("#ffffff") {
            "#fff".to_string()
        } else if value.eq_ignore_ascii_case("#0000ff") {
            "#00f".to_string()
        } else if value.eq_ignore_ascii_case("#000000") {
            "#000".to_string()
        } else if value.eq_ignore_ascii_case("#ffff00") {
            "#ff0".to_string()
        } else if value == "#fff" {
            "#fff".to_string()
        } else if value == "0px" {
            "0".to_string()
        } else if value == "0.5" {
            ".5".to_string()
        } else {
            value.to_string()
        };

        normalized
    }
}
