use crate::parser::{Stylesheet, CssRule, Declaration};

pub struct CssMinifier;

impl CssMinifier {
    pub fn new() -> Self {
        CssMinifier
    }

    pub fn minify(&self, stylesheet: &Stylesheet) -> String {
        let mut output = String::new();

        for rule in &stylesheet.rules {
            output.push_str(&self.minify_rule(rule));
        }

        if !output.is_empty() {
            output.push('\n');
        }
        output
    }

    pub fn minify_str(&self, input: &str) -> String {
        // Simple minification of already formatted CSS
        let result: String = input
            .lines()
            .map(|line| line.trim())
            .filter(|line| !line.is_empty())
            .collect::<Vec<_>>()
            .join("");

        if !result.is_empty() && !result.ends_with('\n') {
            format!("{}\n", result)
        } else {
            result
        }
    }

    fn minify_rule(&self, rule: &CssRule) -> String {
        match rule {
            CssRule::StyleRule { selector, declarations } => {
                self.minify_style_rule(selector, declarations)
            }
            CssRule::AtRule { name, params, rules } => {
                self.minify_at_rule(name, params, rules.as_ref())
            }
            CssRule::Comment(_) => String::new(),
        }
    }

    fn minify_style_rule(&self, selector: &str, declarations: &[Declaration]) -> String {
        let mut output = String::new();
        output.push_str(selector);
        output.push_str("{");

        // Sort declarations by property name
        let mut sorted_decls = declarations.to_vec();
        sorted_decls.sort_by(|a, b| a.property.cmp(&b.property));

        for (i, decl) in sorted_decls.iter().enumerate() {
            output.push_str(&decl.property);
            output.push(':');
            output.push_str(&self.normalize_value(&decl.value));
            if i < sorted_decls.len() - 1 {
                output.push(';');
            }
        }

        output.push_str("}");

        output
    }

    fn minify_at_rule(&self, name: &str, params: &str, rules: Option<&Vec<CssRule>>) -> String {
        let mut output = String::new();
        output.push('@');
        output.push_str(name);

        if !params.is_empty() {
            output.push(' ');
            output.push_str(params);
        }

        if let Some(nested_rules) = rules {
            output.push_str("{");

            for rule in nested_rules {
                output.push_str(&self.minify_rule(rule));
            }

            output.push_str("}");
        } else {
            output.push(';');
        }

        output
    }

    fn normalize_value(&self, value: &str) -> String {
